$pictures = [ordered]@{
  'koeksisters.png' = ''
  'bread.png' = ''
  'rolls.png' = ''
  'cake.png' = ''
  'shop.png' = ''
  'logo.png' = ''
  'pie.png' = ''
  'img\cake.png' = ''
  'img\logo.png' = ''
  'img\bread.png' = ''
  'img\pie.png' = ''
}
$dir = 'C:\sims\files\cathtml-files1112\botha'
New-Item -ItemType Directory -Force (Join-Path $dir 'img') | Out-Null
$utf8 = New-Object System.Text.UTF8Encoding($false)
foreach ($name in $files.Keys) { [IO.File]::WriteAllText((Join-Path $dir $name), $files[$name].Replace("`r`n", "`n").Replace("`n", "`r`n") + "`r`n", $utf8); "wrote $name" }
foreach ($name in $pictures.Keys) { [IO.File]::WriteAllBytes((Join-Path $dir $name), [Convert]::FromBase64String($pictures[$name])); "wrote $name" }
$cloud = 'G:\My Drive\CAT\HTML\botha'
if (Test-Path 'G:\My Drive') {
  New-Item -ItemType Directory -Force (Join-Path $cloud 'img') | Out-Null
  Copy-Item (Join-Path $dir '*') $cloud -Recurse -Force
  "copied to $cloud"
} else { 'NO G:\My Drive - the cloud copy was not made' }